"""Original clinically applied immunology questions."""
from qbank_authoring import question,ref
rows=[]
CO=ref('ARUP complement deficiency testing algorithm','https://arupconsult.com/sites/default/files/Complement%20Deficiency%20Testing%20Algorithm.pdf')
HA=ref('WAO hereditary angioedema guideline: 2025, published 2026','https://pmc.ncbi.nlm.nih.gov/articles/PMC13184495/')
def q(stem,answer,others,title,principle,details,application,clinical,table,refs,style='direct'):
    rows.append(question(stem,answer,others,title,principle,details,application,clinical,table,refs,style))

q('Which feature most directly distinguishes conventional adaptive immune responses from innate pattern recognition?', 'Antigen-specific lymphocyte receptors generated by somatic rearrangement and clonal memory',[
 ('Recognition of shared microbial patterns by germline-encoded receptors','This describes a major innate recognition mechanism.'),('Immediate neutrophil phagocytosis without prior exposure','This is an innate effector function.'),('Complement activation through a microbial-surface pathway','This is part of innate humoral defense, although complement can interact with antibodies.')],
 'Distinguish receptor generation from response timing alone','**Adaptive B- and T-cell responses use clonally distributed antigen receptors.**',['Specific clones expand after antigen recognition.','Innate and adaptive pathways cooperate rather than operate as isolated systems.'], '**Use the defect pattern to interpret infection and autoimmunity phenotypes.**',['Antibody, T-cell, phagocyte and complement defects produce different susceptibilities.','A single infection is rarely sufficient to classify an immune defect.'],[['Adaptive','Clonal antigen specificity'],['Innate','Pattern recognition and rapid effectors'],['Clinical assessment','Pattern of infections and immune dysfunction']],[ref('NIAID immune-system overview','https://www.niaid.nih.gov/research/immune-system-overview')])

q('Immediate urticaria, bronchospasm and hypotension minutes after an allergen exposure most directly reflect which immune mechanism?', 'IgE-mediated mast-cell activation',[
 ('Immune-complex deposition','This more characteristically produces a delayed serum-sickness-type pattern.'),('T-cell-mediated delayed hypersensitivity','This is associated with delayed responses such as contact dermatitis.'),('Direct anti-basement-membrane IgG injury','This is a tissue-targeted antibody mechanism with a different phenotype.')],
 'Recognize the immediate allergic pathway','**Cross-linking of allergen-specific IgE on mast cells can trigger mediator release.**',['Anaphylaxis is a clinical diagnosis and can also have non-IgE mechanisms.','Normal tryptase does not exclude every anaphylactic event.'], '**Treat a compatible life-threatening reaction promptly.**',['Intramuscular epinephrine is first-line acute treatment.','Antihistamines do not replace epinephrine for airway or circulatory compromise.'],[['Type I','IgE/mast-cell pattern'],['Type III','Immune complexes'],['Type IV','T-cell-mediated delay']],[ref('WAO anaphylaxis guidance','https://pmc.ncbi.nlm.nih.gov/articles/PMC7607509/')],style='clinical_scenario')

q('Anti-GBM disease with antibody binding directly to basement-membrane antigen is which classic hypersensitivity category?', 'Type II antibody-mediated hypersensitivity',[
 ('Type I','This is the immediate IgE/mast-cell category.'),('Type III','This refers to soluble immune-complex deposition rather than this direct tissue-antigen pattern.'),('Type IV','This refers to delayed T-cell-mediated responses.')],
 'Differentiate tissue-bound antibody injury from circulating complexes','**Type II includes antibodies directed against cell or tissue antigens.**',['Anti-GBM disease produces characteristic linear immunostaining.','The clinical syndrome can involve kidney and lung.'], '**Use the mechanism to understand the diagnostic test.**',['Linear staining differs from granular immune-complex deposits.','A real pulmonary-renal emergency requires urgent organ-directed care.'],[['Type II','Tissue-directed antibody'],['Type III','Deposited immune complexes'],['Anti-GBM','Linear staining pattern']],[ref('KDIGO glomerular disease guideline: anti-GBM disease','https://kdigo.org/guidelines/gd/')])

q('Fever, rash, arthralgia and complement consumption several days after exposure to a foreign protein are characteristic of which mechanism?', 'Immune-complex-mediated type III hypersensitivity',[
 ('Immediate type I mast-cell activation','This usually has a different rapid timing and allergic phenotype.'),('Type II receptor-stimulating antibody disease','This is not the typical serum-sickness mechanism.'),('Type IV contact hypersensitivity','This is a T-cell-mediated delayed skin response rather than systemic immune-complex disease.')],
 'Serum sickness links circulating antigen-antibody complexes to inflammation','**Immune complexes can activate complement and injure small vessels.**',['The clinical context and timing matter.','Serum-sickness-like reactions can differ in mechanism and complement behavior.'], '**Review the culprit and assess systemic severity.**',['Evaluate renal involvement when symptoms or urine findings suggest it.','Exclude infection or a primary vasculitic disorder when the pattern is uncertain.'],[['Type III','Immune-complex deposition'],['Complement','May be consumed'],['Clinical pattern','Fever/rash/joint symptoms']],[ref('Serum sickness clinical reference','https://www.ncbi.nlm.nih.gov/books/NBK538312/')],style='clinical_scenario')

q('A pruritic eczematous eruption occurs 48 hours after nickel contact. Which mechanism is most likely?', 'T-cell-mediated type IV hypersensitivity',[
 ('IgE-dependent immediate mast-cell activation','This more often causes rapid urticarial symptoms.'),('Antibody-mediated red-cell destruction','This is a type II process with a different target.'),('Circulating immune-complex vasculitis','This is a different inflammatory mechanism and morphology.')],
 'Contact allergy is a delayed cellular response','**Allergic contact dermatitis is mediated primarily by sensitized T cells.**',['Patch testing assesses selected delayed contact allergens.','Irritant dermatitis is a nonallergic alternative and may coexist.'], '**Identify and reduce the relevant exposure.**',['Use morphology, distribution and timing to guide testing.','Do not substitute a routine serum IgE panel for appropriate patch testing.'],[['Contact allergy','Delayed T-cell response'],['Patch test','Relevant investigation'],['Irritant dermatitis','Different mechanism']],[ref('American Academy of Dermatology: contact dermatitis testing','https://www.aad.org/public/diseases/eczema/types/contact-dermatitis/patch-testing')],style='clinical_scenario')

q('A patient with recurrent meningococcal infection has absent CH50 and AH50. Which inherited defect category is particularly important?', 'Terminal complement pathway deficiency',[
 ('An isolated early classical-pathway deficiency with intact alternative pathway','This would more typically reduce CH50 with preserved AH50.'),('An isolated alternative-pathway defect with intact classical pathway','This would more typically reduce AH50 with preserved CH50.'),('Isolated IgA deficiency as the direct cause of absent both-pathway function','An antibody-isotype defect does not itself explain this functional complement pattern.')],
 'Use paired functional assays to localize a complement defect','**Terminal components are shared by the classical and alternative pathways.**',['Both assays can also be low in severe consumption or from sample problems.','Specific component testing confirms the mechanism.'], '**Combine laboratory localization with the infection history.**',['Review meningococcal prevention and education.','Repeat or verify an unexpected result using proper specimen handling.'],[['Low CH50/normal AH50','Early classical-pathway clue'],['Normal CH50/low AH50','Alternative-pathway clue'],['Both low','Shared component/consumption consideration']],[CO],style='clinical_scenario')

q('Recurrent angioedema without wheals, abdominal attacks, low C4 and low C1-inhibitor function suggest which mechanism?', 'Bradykinin-mediated C1-inhibitor-related angioedema',[
 ('Typical histamine-mediated urticaria alone','The lack of wheals, abdominal phenotype and complement pattern suggest another mechanism.'),('Primary immune-complex urticarial vasculitis','This has a different persistent wheal/purpura pattern.'),('IgE allergy proven by low C4','Low C4 does not establish an IgE mechanism.')],
 'The mediator determines effective treatment','**C1-inhibitor-related angioedema is driven by excessive bradykinin generation.**',['Family history can be absent, and acquired deficiency is another possibility.','C1-inhibitor quantity and function help distinguish types; selected hereditary forms have normal C1 inhibitor.'], '**Assess airway risk immediately during attacks.**',['Antihistamines and glucocorticoids are not reliable targeted treatment for bradykinin swelling.','Evaluate family history, age of onset and possible acquired causes.'],[['Bradykinin','No typical wheals'],['Histamine','Often urticaria/itch'],['Tests','C4 plus C1-inhibitor quantity/function']],[HA],style='clinical_scenario')

q('Which on-demand treatment directly blocks the bradykinin B2 receptor in hereditary angioedema?', 'Icatibant',[
 ('Lanadelumab','This inhibits plasma kallikrein and is used for prevention rather than B2 receptor blockade.'),('Omalizumab','This targets IgE and does not directly block bradykinin B2 receptors.'),('C1-inhibitor concentrate','This replaces the deficient regulator rather than directly antagonizing B2 receptors.')],
 'Know the targeted acute-treatment mechanism','**Icatibant antagonizes the bradykinin B2 receptor.**',['C1-inhibitor concentrate and other current on-demand options act through different mechanisms.','Newer oral kallikrein inhibition options exist in appropriate jurisdictions and age groups.'], '**Treat attacks early and secure emergency care for airway involvement.**',['Availability and licensing differ by country.','Every patient needs a clear rescue and emergency plan even when on long-term prophylaxis.'],[['Icatibant','B2 receptor'],['C1-inhibitor','Replacement'],['Lanadelumab','Kallikrein-directed prophylaxis']],[HA])

q('An adult has recurrent bacterial sinus and lung infections, persistently low IgG and IgA and poor vaccine responses. B cells are present and secondary causes are excluded. Which diagnosis is most likely?', 'Common variable immunodeficiency',[
 ('Selective IgA deficiency','This does not explain substantially reduced IgG and poor broader antibody function.'),('X-linked agammaglobulinemia as proven solely from infection history','This more characteristically has profoundly reduced/absent B cells and a different developmental defect.'),('Terminal complement deficiency','This does not explain the stated quantitative antibody abnormalities.')],
 'CVID is an exclusion-based antibody-deficiency diagnosis','**Low immunoglobulins with impaired antibody function can support CVID after appropriate exclusions.**',['Protein loss, medications including B-cell depletion, malignancy and other immune defects must be considered.','Autoimmunity and lymphoproliferation can coexist with infections.'], '**Assess infection burden, lung damage and immune dysfunction.**',['Immunoglobulin replacement can be indicated after specialist assessment.','A single low value during acute illness is not the full diagnosis.'],[['IgG/IgA','Persistently reduced'],['Vaccine response','Functional assessment'],['Secondary causes','Must be excluded']],[ref('ICON international CVID consensus','https://pmc.ncbi.nlm.nih.gov/articles/PMC4869529/')],style='clinical_scenario')

q('A boy has recurrent bacterial infections after infancy, very small tonsils, nearly absent circulating B cells and profoundly low immunoglobulins. Which molecular defect is characteristic?', 'BTK deficiency',[
 ('CD40 ligand deficiency','This more typically causes a class-switch defect with preserved B cells and a hyper-IgM phenotype.'),('NADPH oxidase deficiency','This causes a phagocyte killing defect rather than absent B-cell maturation.'),('C5 deficiency','This is a complement defect with a different immune profile.')],
 'XLA interrupts B-cell development','**BTK defects cause a maturation block leading to agammaglobulinemia and very low B cells.**',['Other genes can cause autosomal agammaglobulinemia phenotypes.','Maternal antibodies can temporarily protect early infancy.'], '**Confirm the immune phenotype and genetic cause.**',['Provide immunoglobulin replacement and appropriate infection care.','Avoid live vaccines that are unsafe for the specific immune defect.'],[['BTK','B-cell development'],['CD40L','Class switching'],['NADPH oxidase','Phagocyte oxidative burst']],[ref('GeneReviews: X-linked agammaglobulinemia','https://www.ncbi.nlm.nih.gov/books/NBK1453/')],style='clinical_scenario')

q('A child has recurrent Serratia and Aspergillus infections, deep abscesses and granulomatous inflammation. Which screening test is most useful for the suspected phagocyte defect?', 'Neutrophil dihydrorhodamine oxidative-burst assay',[
 ('CH50 alone','This assesses complement rather than neutrophil oxidase function.'),('Serum IgE alone','This cannot establish the oxidative-burst defect.'),('Anti-CCP','This does not investigate a congenital phagocyte killing disorder.')],
 'CGD is a failure of oxidative microbial killing','**NADPH oxidase dysfunction predisposes to characteristic bacterial and fungal infections.**',['DHR flow cytometry is a principal functional test.','MPO deficiency and uncommon CGD subtypes require expert interpretation of the result.'], '**Confirm the genetic and functional phenotype.**',['Plan antimicrobial prevention, exposure counseling and specialist definitive-treatment assessment.','Granulomatous inflammation does not mean the patient has sarcoidosis.'],[['CGD','Oxidative-burst defect'],['DHR','Functional screening'],['Genetics','Defines subtype/inheritance']],[ref('GeneReviews: chronic granulomatous disease','https://www.ncbi.nlm.nih.gov/books/NBK99496/')],style='clinical_scenario')

q('Delayed umbilical separation, severe bacterial infections with little pus and marked neutrophilia most strongly suggest which defect?', 'Leukocyte adhesion deficiency',[
 ('Chronic granulomatous disease','This is a killing defect; the classic absent-pus/delayed-cord phenotype suggests defective recruitment.'),('X-linked agammaglobulinemia','This is a humoral defect rather than a neutrophil migration defect.'),('Terminal complement deficiency','This classically increases susceptibility to Neisseria, not this recruitment phenotype.')],
 'High circulating neutrophils can coexist with poor tissue defense','**Adhesion defects impair neutrophil migration out of the bloodstream.**',['LAD-I commonly involves CD18/beta2-integrin expression or function.','The cells may be numerous in blood but fail to reach infected tissue effectively.'], '**Use specialist flow-cytometric and genetic assessment.**',['Treat infection urgently.','Definitive therapy and prevention depend on subtype and severity.'],[['Blood neutrophils','Often high'],['Tissue pus','May be scant'],['Mechanism','Adhesion/transmigration defect']],[ref('NLM MedlinePlus: leukocyte adhesion deficiency type 1','https://medlineplus.gov/genetics/condition/leukocyte-adhesion-deficiency-type-1/')],style='clinical_scenario')

q('Recurrent staphylococcal skin abscesses, eczema, very high IgE, retained primary teeth and characteristic skeletal findings suggest which syndrome?', 'STAT3-associated hyper-IgE syndrome',[
 ('DOCK8 deficiency','Severe cutaneous viral infection and allergy are prominent in that combined immune-deficiency phenotype, with different skeletal/dental associations.'),('Selective IgA deficiency','This does not explain the characteristic staphylococcal and skeletal/dental pattern.'),('C1-inhibitor deficiency','This causes a different angioedema phenotype.')],
 'Very high IgE is not a complete diagnosis','**STAT3-associated disease combines immune susceptibility with characteristic nonimmune findings.**',['Different hyper-IgE disorders have different infection and malignancy risks.','Phenotype and molecular testing distinguish them.'], '**Assess lung complications and infection prevention.**',['Do not assume severe eczema alone establishes the syndrome.','Genetic diagnosis guides counseling and treatment decisions.'],[['STAT3-HIES','Dental/skeletal clues'],['DOCK8','Viral/allergic combined-deficiency clues'],['IgE alone','Insufficient']],[ref('GeneReviews: STAT3 hyper-IgE syndrome','https://www.ncbi.nlm.nih.gov/books/NBK25507/')])

q('A boy has recurrent bacterial and opportunistic infections, low IgG/IgA, normal or raised IgM and a CD40-ligand defect. Which immune function is impaired?', 'T-cell help for B-cell class switching and related immune activation',[
 ('BTK-dependent early B-cell maturation alone','That causes a different near-absent-B-cell agammaglobulinemia pattern.'),('Terminal membrane-attack-complex formation','This is a complement function.'),('Neutrophil NADPH oxidase activity as the defining defect','This is the CGD mechanism.')],
 'Hyper-IgM can represent more than a simple antibody-isotype problem','**CD40L deficiency disrupts class switching and important cellular immune interactions.**',['B cells are generally present, but switched antibody production is impaired.','PJP and selected other opportunistic infections can occur.'], '**Assess the combined infection risk and definitive-treatment options.**',['Replacement immunoglobulin and appropriate prophylaxis may be needed.','Genetic confirmation guides family counseling.'],[['CD40L','T-cell help/class switching'],['B cells','Usually present'],['Opportunistic risk','Requires attention']],[ref('GeneReviews: CD40 ligand deficiency','https://www.ncbi.nlm.nih.gov/books/NBK1402/')])

if __name__=='__main__':print(f'Immunology/safety draft: {len(rows)} questions')
